use std::path::Path;

use unicodex_core::{decode_node, encode_value_node, Node, ObjectStore, RefStatus, Value};

pub fn forge_component_root(
    cwd: &Path,
    root_cid: &str,
    component_cid: &str,
    root_field: &str,
    injected_value: &str,
) -> String {
    let store = ObjectStore::open(cwd);
    let component_bytes = store.get_canonical(component_cid).unwrap();
    let Node::Value(mut component) = decode_node(&component_bytes).unwrap() else {
        panic!("protocol component must be a value node")
    };
    map_mut(&mut component).push((
        Value::Text("ambient_authority".to_owned()),
        Value::Text(injected_value.to_owned()),
    ));
    let forged_component = store
        .put_canonical(&encode_value_node(&component).unwrap())
        .unwrap();
    assert_eq!(store.verify_object(&forged_component).status, RefStatus::Ok);

    let root_bytes = store.get_canonical(root_cid).unwrap();
    let Node::Value(mut root) = decode_node(&root_bytes).unwrap() else {
        panic!("runtime descriptor must be a value node")
    };
    set_field(&mut root, root_field, Value::Ref(forged_component));
    store
        .put_canonical(&encode_value_node(&root).unwrap())
        .unwrap()
}

fn set_field(value: &mut Value, key: &str, replacement: Value) {
    let target = map_mut(value)
        .iter_mut()
        .find_map(|(field, value)| match field {
            Value::Text(field) if field == key => Some(value),
            _ => None,
        })
        .unwrap_or_else(|| panic!("missing descriptor field {key}"));
    *target = replacement;
}

fn map_mut(value: &mut Value) -> &mut Vec<(Value, Value)> {
    let Value::Map(entries) = value else {
        panic!("descriptor must be a map")
    };
